"""Add clearly fictional tracking examples to an existing demo-only account.

Docker: python tracking_demo.py meeting_demo
No external calls, messages, applications, or AI usage. Repeat-safe.
"""
import hashlib
import json
import sys
from app import db, config
from app.models import ApplicationInput
username=sys.argv[1] if len(sys.argv)>1 else 'meeting_demo'
if username!='meeting_demo' and not username.startswith('demo_'):
    raise SystemExit('Use an existing meeting_demo or demo_ account; personal accounts are excluded.')
with db.connect() as c: row=c.execute('SELECT id FROM users WHERE username=?',(username,)).fetchone()
if not row: raise SystemExit('Create the fictional demo account first.')
user=row['id'];added=0
for i,value in enumerate(json.loads((config.CONTENT_DIR/'application_demo.json').read_text())):
    entity_id=hashlib.sha256((user+':tracking-demo:'+str(i)).encode()).hexdigest()[:32]
    if db.get(user,entity_id): continue
    data=ApplicationInput.model_validate({**value,'notes':'FICTIONAL CLASSROOM EXAMPLE. No real application was submitted.','posting_snapshot':{'title':value['title'],'company':value['company'],'description':'Fictional posting for demonstrating application tracking.','url':''}}).model_dump()
    db.save(user,'application',data,entity_id);added+=1
print(json.dumps({'fictional_applications_added':added,'external_requests':0}))
# A clearly labelled canned comparison for the fictional analyst walkthrough.
# It exercises the same validation/scorer as live results without an API call.
from app import comparison
jobs=db.list_entities(user,'job');experiences=db.list_entities(user,'experience')
job=next((r for r in jobs if 'Use SQL and Excel to prepare reports.' in r['data'].get('description','')),None)
if job:
    comparison_id=hashlib.sha256((user+':comparison-demo').encode()).hexdigest()[:32]
    if not db.get(user,comparison_id):
        project=next((r for r in experiences if r['data'].get('category')=='project' and 'SQL' in r['data'].get('description','')),None)
        employment=next((r for r in experiences if r['data'].get('category')=='employment' and 'Excel' in r['data'].get('description','')),None)
        if project and employment:
            guide=json.loads((config.CONTENT_DIR/'guidance.json').read_text())[0]
            retrieved=[{'id':r['id'],'kind':'experience','data':r['data']} for r in experiences if r['data'].get('confirmed')]+[{'id':guide['id'],'kind':'guidance','data':guide}]
            original=project['data']['description'].split('. ')[0]
            output={'summary':'FICTIONAL DEMONSTRATION: this canned comparison was not generated by AI. Confirmed class work supports SQL and a campus job supports Excel. Git needs more information.','requirements':[
                {'keyword':'SQL','job_quote':'Use SQL and Excel to prepare reports.','kind':'qualification','importance':'required','status':'supported','evidence':[{'record_id':project['id'],'quote':original}],'explanation':'The class project documents SQL use; it remains academic project experience.','question':''},
                {'keyword':'Excel','job_quote':'Use SQL and Excel to prepare reports.','kind':'qualification','importance':'required','status':'supported','evidence':[{'record_id':employment['id'],'quote':employment['data']['description']}],'explanation':'The bookstore role documents inventory and sales reporting in Excel.','question':''},
                {'keyword':'Git','job_quote':'Git is preferred.','kind':'qualification','importance':'preferred','status':'unknown','evidence':[],'explanation':'The fictional profile does not yet describe Git use. This does not establish a lack of ability.','question':'Have you used Git in a class or project?'}
            ],'job_details':[],'recommendations':[{'record_id':r['id'],'reason':'Relevant confirmed classroom or reporting experience.','evidence':[{'record_id':r['id'],'quote':r['data']['description']}]} for r in experiences if r['data'].get('confirmed') and r['data'].get('description')],
            'suggestions':[{'record_id':project['id'],'original':original,'proposed':original,'reason':'Keep the SQL example visible and retain its classroom context. Demonstration wording is intentionally unchanged.','guide_id':guide['id'],'guide_quote':guide['text']}],'questions':[]}
            comparison.validate(output,job['data'],retrieved,{})
            db.save(user,'analysis',{**output,'job_id':job['id'],'posting_snapshot':job['data'],'retrieved':retrieved,'ai':{'model':'Fictional fixture — no AI request','mode':'economy','reasoning_effort':'none','usage':{'input_tokens':0,'output_tokens':0,'total_tokens':0}}},comparison_id)
            print(json.dumps({'fictional_comparison_added':True,'external_requests':0}))
